package com.dunerealms.atelier;
import com.example.dunegui.NativeMenus;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.event.ClickEvent;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.LeatherArmorMeta;import org.bukkit.persistence.PersistentDataType;import org.bukkit.plugin.java.JavaPlugin;
import java.sql.*;import java.util.*;import java.util.concurrent.*;import java.util.function.Consumer;
/** Shared illustrated menu renderer; paid orders retain their authoritative inventory checkpoint. */
public final class DuneAtelier extends JavaPlugin implements CommandExecutor {
 private JavaPlugin core;private Driver driver;private Properties auth;private String url;private volatile boolean ready;
 private final DeliveryStore store=new DeliveryStore();private final Set<UUID> busy=new HashSet<>();
 private final ExecutorService worker=Executors.newFixedThreadPool(2,r->{Thread t=new Thread(r,"DuneAtelier-reader");t.setDaemon(true);return t;});
 public void onEnable(){core=(JavaPlugin)getServer().getPluginManager().getPlugin("DuneCore");getCommand("duneatelier").setExecutor(this);try{url=core.getConfig().getString("database.jdbc-url","");if(!url.startsWith("jdbc:mysql:"))throw new IllegalStateException();auth=new Properties();auth.setProperty("user",core.getConfig().getString("database.username",""));auth.setProperty("password",core.getConfig().getString("database.password",""));auth.setProperty("connectTimeout","3000");auth.setProperty("socketTimeout","5000");auth.setProperty("allowPublicKeyRetrieval","true");driver=(Driver)Class.forName("com.mysql.cj.jdbc.Driver",true,core.getClass().getClassLoader()).getDeclaredConstructor().newInstance();verifyFactory();worker.execute(()->{try(Connection c=connect();Statement q=c.createStatement()){q.executeQuery("SELECT id FROM dune_kit_sales LIMIT 0").close();ready=true;getLogger().info("Paid kit deliveries ready; no starter items or funds generated.");}catch(Exception e){getLogger().severe("Commerce schema unavailable; item delivery disabled.");}});getServer().getScheduler().runTaskTimer(this,()->{for(Player p:getServer().getOnlinePlayers())queued(p);},200,300);}catch(Exception e){getLogger().severe("Private shared MySQL configuration required.");}}
 public void onDisable(){ready=false;worker.shutdownNow();}
 private Connection connect()throws SQLException{Connection c=driver.connect(url,auth);if(c==null)throw new SQLException("No SQL driver");return c;}
 private void main(Runnable r){if(isEnabled())getServer().getScheduler().runTask(this,r);}
 static boolean entryAllowed(Player p){return p.isOnline()&&p.hasPermission("dune.atelier.view");}
 private boolean allowed(Player p){return ready&&entryAllowed(p);}
 static Runnable guarded(Player p,Runnable action){return ()->{if(entryAllowed(p))action.run();else p.sendMessage("Atelier menu access changed. Reopen your account menu.");};}
 private NativeMenus.Choice choice(Player p,String title,String description,Runnable action){return new NativeMenus.Choice(title,description,guarded(p,action));}
 private NativeMenus.Choice choice(Player p,String title,String description,Runnable action,String image){return new NativeMenus.Choice(title,description,guarded(p,action),image);}
 private Inventory loading(Player p){Inventory model=Bukkit.createInventory(null,9,"Atelier - Loading");NativeMenus.inventory(this,p,"Atelier - Loading",model,Map.of(),()->allowed(p));return model;}
 boolean current(Player p,Inventory model){return allowed(p)&&NativeMenus.isCurrent(p,model);}
 public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(sender instanceof Player p&&allowed(p))menu(p);else sender.sendMessage("Kits Exchange requires an active shared profile and menu access.");return true;}
 private void website(Player p,String path){if(!allowed(p))return;p.sendMessage(Component.text("Open Kits Exchange",NamedTextColor.GOLD).clickEvent(ClickEvent.openUrl("https://cp.dunerealms.com/"+path)));}
 private void menu(Player p){if(!allowed(p)||!busy.add(p.getUniqueId()))return;Inventory loading=loading(p);worker.execute(()->{try(Connection c=connect()){List<DeliveryStore.Pending> pending=store.pending(c,p.getUniqueId(),false);main(()->{busy.remove(p.getUniqueId());if(!current(p,loading))return;List<NativeMenus.Choice> choices=new ArrayList<>();choices.add(choice(p,"Kits Exchange","Browse designs, prices and confirmed sales.",()->website(p,"#kits-exchange"),"https://www.dunerealms.com/assets/gui/imperial-portal.png"));choices.add(choice(p,"The Loom of the Desert","Review your five sales chapters and claim treasury-funded rewards.",()->arc(p)));for(var item:pending)choices.add(choice(p,"Receive "+item.name(),item.quality().replace('_',' ')+" - Four pieces - Already paid",()->deliver(p,UUID.fromString(item.id()))));choices.add(choice(p,"Refresh","Check confirmed purchases.",()->menu(p)));NativeMenus.show(this,p,"Imperial Atelier",pending.isEmpty()?"No unclaimed paid kit orders. Website purchases issue personal redeem codes.":"Only your paid orders appear here. Make four empty inventory slots before receiving a kit.",choices);});}catch(Exception e){main(()->{busy.remove(p.getUniqueId());if(current(p,loading))p.sendMessage("Kit receipts are unavailable; no items changed.");});}});}
 private void arc(Player p){if(!allowed(p)||!busy.add(p.getUniqueId()))return;Inventory loading=loading(p);worker.execute(()->{try(Connection c=connect()){List<ArcStore.Chapter> chapters=new ArcStore().read(c,p.getUniqueId());main(()->{busy.remove(p.getUniqueId());if(!current(p,loading))return;List<NativeMenus.Choice> choices=new ArrayList<>();StringBuilder text=new StringBuilder("Sell your own designs to other players. Only paid, delivered kits count; one buyer per tier per UTC day.\n\n");for(var chapter:chapters){text.append(chapter.title()).append("\n").append(chapter.description()).append("\nDesign: ").append(chapter.templateName()).append("\n").append(chapter.quality().replace('_',' ')).append(" · ").append(chapter.sales()).append('/').append(chapter.target()).append(" sales · ").append(chapter.reward().toPlainString()).append(" Dunemarks · ").append(chapter.claimed()?"Claimed":chapter.unlocked()?"In progress":"Locked").append("\n\n");if(chapter.canClaim())choices.add(choice(p,"Claim "+chapter.title(),chapter.reward().toPlainString()+" Dunemarks from the server treasury",()->claimReward(p,chapter.index())));}choices.add(choice(p,"Refresh","Read confirmed sales progress.",()->arc(p)));choices.add(choice(p,"Back","Return to paid kit deliveries.",()->menu(p)));NativeMenus.show(this,p,"The Loom of the Desert",text.toString(),choices);});}catch(Exception e){main(()->{busy.remove(p.getUniqueId());if(current(p,loading))p.sendMessage("Sales progress is unavailable. No reward changed.");});}});}
 private void claimReward(Player p,int index){if(!allowed(p)||!busy.add(p.getUniqueId()))return;UUID player=p.getUniqueId();Inventory loading=loading(p);worker.execute(()->{try(Connection c=connect()){c.setAutoCommit(false);try{ArcStore.Claim result=new ArcStore().claim(c,player,index);c.commit();main(()->{busy.remove(player);if(current(p,loading)){p.sendMessage(result==ArcStore.Claim.credited?"Chapter reward transferred from the server treasury.":result==ArcStore.Claim.already_claimed?"This chapter reward was already claimed.":"Your reward is pending server treasury funding. You can retry later.");arc(p);}});}catch(Exception e){c.rollback();throw e;}}catch(Exception e){main(()->{busy.remove(player);if(current(p,loading))p.sendMessage("Reward was not committed. No currency was created.");});}});}
 private void queued(Player p){if(!allowed(p)||!p.hasPermission("dune.atelier.redeem")||!busy.add(p.getUniqueId()))return;worker.execute(()->{try(Connection c=connect()){List<DeliveryStore.Pending> rows=store.pending(c,p.getUniqueId(),true);main(()->{busy.remove(p.getUniqueId());if(!rows.isEmpty()&&allowed(p)&&empty(p)>=4)deliver(p,UUID.fromString(rows.getFirst().id()));});}catch(Exception e){main(()->busy.remove(p.getUniqueId()));}});}
 static int empty(Player p){int n=0;for(ItemStack i:p.getInventory().getStorageContents())if(i==null||i.getType().isAir())n++;return n;}
 private void deliver(Player p,UUID order){if(!allowed(p)||!p.hasPermission("dune.atelier.redeem")||!busy.add(p.getUniqueId()))return;try{if(empty(p)<4){p.sendMessage("Make four empty inventory slots; your paid kit stays pending.");return;}Consumer<Connection> operation=c->{try{if(!allowed(p)||!p.hasPermission("dune.atelier.redeem"))throw new IllegalStateException("Delivery permission changed");DeliveryStore.Design design=store.lock(c,p.getUniqueId(),order);List<ItemStack> pieces=kit(p,design,order);for(ItemStack item:pieces)if(!p.getInventory().addItem(item).isEmpty())throw new IllegalStateException("Inventory capacity changed");store.delivered(c,p.getUniqueId(),order,System.currentTimeMillis());}catch(Exception e){throw new IllegalStateException("Paid kit delivery refused",e);}};core.getClass().getMethod("transactNetworkInventory",Player.class,Consumer.class).invoke(core,p,operation);p.sendMessage("Your paid kit has been delivered. Its item code is now used.");}catch(Exception e){p.sendMessage("Delivery was not committed. Your paid receipt stays available.");}finally{busy.remove(p.getUniqueId());}}
 private List<ItemStack> kit(Player p,DeliveryStore.Design d,UUID order)throws Exception{String faction=String.valueOf(core.getClass().getMethod("factionOf",Player.class).invoke(core,p));if(!Set.of("Fremen","Harkonnen","Corrino","Atreides","Ordos").contains(faction))throw new IllegalStateException("Select a playable faction first");Object raw=core.getClass().getMethod("createFactionKit",String.class).invoke(core,faction);if(!(raw instanceof List<?> base))throw new IllegalStateException("Faction factory unavailable");return KitFactory.decorate(base,d,order);}
 private void verifyFactory()throws Exception{for(String faction:List.of("Fremen","Harkonnen","Corrino","Atreides","Ordos")){Object raw=core.getClass().getMethod("createFactionKit",String.class).invoke(core,faction);if(!(raw instanceof List<?> base))throw new IllegalStateException("Faction factory unavailable");for(String quality:DeliveryStore.TIERS)KitFactory.verify(base,new DeliveryStore.Design(UUID.randomUUID().toString(),"Transient factory verification","#123456",List.of("Not issued to a player."),quality));}getLogger().info("25 faction/rarity factory cases passed; no inventory or balances touched.");}
}